\label{Rem:NovikovMultVar}
  \def[t_1^\Gamma, \dotsc, t_n^\Gamma]{[t_1^\Gamma, \dotsc, t_n^\Gamma]}
  \def[t_1^{\Gamma_{\ge 0}}, \dotsc, t_n^{\Gamma_{\ge 0}}]{[t_1^{\Gamma_{\ge 0}}, \dotsc, t_n^{\Gamma_{\ge 0}}]}
  As in Remark~\ref{Rem:NovikovOneVar}, we may construct the Novikov rings
  $A(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$ as a completion of the polynomial ring $A[t_1^\Gamma, \dotsc, t_n^\Gamma]$. Here, we
  given $A[t_1^\Gamma, \dotsc, t_n^\Gamma]$ the topology generated by additive cosets of
  \[
    \bigoplus_{d_1, \dotsc, d_n \in \Gamma, \sum_j s_j d_j \ge C} A t_1^{d_1}
    \dotsm t_n^{d_n}
  \]
  where $s_1, \dotsc, s_n \in \mathbb{R}_{> 0}$ and $C \in \mathbb{R}$. This
  is indeed a topological ring, and its completion is $A(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$. One can
  similarly define a topological $A[t_1^\Gamma, \dotsc, t_n^\Gamma]$-module $M[t_1^\Gamma, \dotsc, t_n^\Gamma]$ whose
  completion is $M(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$. In particular, it follows from this discussion
  that $A(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$ indeed has a natural ring structure, and $M(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$
  indeed has a natural structure of a module over it.

\label{Lem:NovikovExact}
  The functor from $A$-modules to $A(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$-modules sending $M \mapsto
  M(\!( t_1^\Gamma, \dotsc, t_n^\Gamma )\!)$ is exact.

\label{Prop:VectToIsocFullyFaithful}
  For every ring $A$, the functor $\mathsf{Vect}(A) \to \mathsf{NovIsoc}(A)$ is fully
  faithful.

\label{Lem:GlobalSection}
  We have
  \begin{align*}
    H^0(X \times_Y X, \mathscr{O}_{X \times_Y X}) &= A\dparen[t][u], \\ H^0(X
    \times_Y X \times_Y X, \mathscr{O}_{X \times_Y X \times_Y X}) &=
    A\dparen[t][u][v].
  \end{align*}
